using System.Data;
using Microsoft.Data.SqlClient;
using RequestTracker.Domain;

namespace RequestTracker.Seeder;

/// <summary>Streams requests into the Requests table with SqlBulkCopy, one batch at a time, inside one transaction.</summary>
public static class RequestBulkWriter
{
    public const int BatchSize = 10_000;

    private static readonly string[] Columns =
        ["Title", "OrganizationName", "Status", "Priority", "AssignedTo", "CreatedAt", "UpdatedAt"];

    /// <summary>Id and RowVersion are generated by the database, so they are not mapped.</summary>
    public static async Task<int> WriteAsync(
        string connectionString,
        IEnumerable<Request> requests,
        Action<int> onBatchWritten,
        CancellationToken cancellationToken)
    {
        await using var connection = new SqlConnection(connectionString);
        await connection.OpenAsync(cancellationToken);
        await using var transaction = (SqlTransaction)await connection.BeginTransactionAsync(cancellationToken);

        using var bulkCopy = new SqlBulkCopy(connection, SqlBulkCopyOptions.TableLock, transaction)
        {
            DestinationTableName = "Requests",
            BatchSize = BatchSize,
            BulkCopyTimeout = 0,
        };
        foreach (var column in Columns)
        {
            bulkCopy.ColumnMappings.Add(column, column);
        }

        var total = 0;
        using var table = CreateTable();
        foreach (var request in requests)
        {
            table.Rows.Add(
                request.Title,
                request.OrganizationName,
                (byte)request.Status,
                (byte)request.Priority,
                (object?)request.AssignedTo ?? DBNull.Value,
                request.CreatedAt,
                request.UpdatedAt);

            if (table.Rows.Count == BatchSize)
            {
                total += await FlushAsync(bulkCopy, table, onBatchWritten, total, cancellationToken);
            }
        }

        if (table.Rows.Count > 0)
        {
            total += await FlushAsync(bulkCopy, table, onBatchWritten, total, cancellationToken);
        }

        await transaction.CommitAsync(cancellationToken);
        return total;
    }

    private static async Task<int> FlushAsync(
        SqlBulkCopy bulkCopy, DataTable table, Action<int> onBatchWritten, int totalBefore, CancellationToken cancellationToken)
    {
        var written = table.Rows.Count;
        await bulkCopy.WriteToServerAsync(table, cancellationToken);
        table.Clear();
        onBatchWritten(totalBefore + written);
        return written;
    }

    private static DataTable CreateTable()
    {
        var table = new DataTable();
        table.Columns.Add("Title", typeof(string));
        table.Columns.Add("OrganizationName", typeof(string));
        table.Columns.Add("Status", typeof(byte));
        table.Columns.Add("Priority", typeof(byte));
        table.Columns.Add("AssignedTo", typeof(string));
        table.Columns.Add("CreatedAt", typeof(DateTime));
        table.Columns.Add("UpdatedAt", typeof(DateTime));
        return table;
    }
}
